int main() {
    geo::Vec a{1, 2}, b{3, 4}; geo::Vec c = a + b;
    Array<int, 5> arr{}; for (int i = 0; i < arr.size(); i++) arr[i] = i * i;
    auto square = [](int v) { return v * v; };
    return c.x + c.y + arr[4] + apply(square, 3) + square(2);
}

