typedef int (*compare_fn)(const void *, const void *);

static void swap_items(unsigned char *a, unsigned char *b, unsigned long size) {
    while (size--) {
        unsigned char t = *a;
        *a++ = *b;
        *b++ = t;
    }
}

void quick_sort(void *base, unsigned long count, unsigned long size, compare_fn compare) {
    unsigned char *items = base;
    while (count > 1) {
        unsigned char *last = items + (count - 1) * size;
        swap_items(items + (count / 2) * size, last, size);
        unsigned long store = 0;
        for (unsigned long i = 0; i + 1 < count; i++) {
            if (compare(items + i * size, last) < 0) {
                swap_items(items + i * size, items + store * size, size);
                store++;
            }
        }
        swap_items(items + store * size, last, size);
        unsigned long right = count - store - 1;
        if (store < right) {
            quick_sort(items, store, size, compare);
            items += (store + 1) * size;
            count = right;
        } else {
            quick_sort(items + (store + 1) * size, right, size, compare);
            count = store;
        }
    }
}

