static int is_space(int c) { return c == ' ' || (c >= '\t' && c <= '\r'); }

static int digit_value(int c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'z') return c - 'a' + 10;
    if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
    return 64;
}

long parse_long(const char *text, const char **end, int base) {
    const char *p = text;
    while (is_space((unsigned char)*p)) p++;
    int negative = 0;
    if (*p == '+' || *p == '-') negative = *p++ == '-';
    if ((base == 0 || base == 16) && p[0] == '0' && (p[1] == 'x' || p[1] == 'X') &&
        digit_value((unsigned char)p[2]) < 16) {
        p += 2;
        base = 16;
    } else if (base == 0) {
        base = p[0] == '0' ? 8 : 10;
    }
    unsigned long limit = negative ? 0x8000000000000000UL : 0x7fffffffffffffffUL;
    unsigned long value = 0;
    int any = 0, overflow = 0;
    for (;; p++) {
        int digit = digit_value((unsigned char)*p);
        if (digit >= base) break;
        any = 1;
        if (overflow || value > (limit - digit) / base) overflow = 1;
        else value = value * base + digit;
    }
    if (end) *end = any ? p : text;
    if (overflow) value = limit;
    return negative ? (long)(0 - value) : (long)value;
}

