#include <stdarg.h>

struct sink { char *buffer; unsigned long size; unsigned long length; };

static void put(struct sink *out, char c) {
    if (out->length + 1 < out->size) out->buffer[out->length] = c;
    out->length++;
}

static void put_repeated(struct sink *out, char c, int count) {
    while (count-- > 0) put(out, c);
}

static int digits_of(char *digits, unsigned long value, unsigned base, int upper) {
    const char *set = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    int n = 0;
    do {
        digits[n++] = set[value % base];
        value /= base;
    } while (value);
    return n;
}

static void put_number(struct sink *out, unsigned long magnitude, int negative, unsigned base,
                       int upper, int width, int left, int zero) {
    char digits[24];
    int n = digits_of(digits, magnitude, base, upper);
    int length = n + negative;
    if (!left && !zero) put_repeated(out, ' ', width - length);
    if (negative) put(out, '-');
    if (!left && zero) put_repeated(out, '0', width - length);
    while (n > 0) put(out, digits[--n]);
    if (left) put_repeated(out, ' ', width - length);
}

int format(char *buffer, unsigned long size, const char *fmt, ...) {
    struct sink out = { buffer, size, 0 };
    va_list args;
    va_start(args, fmt);
    for (const char *p = fmt; *p; p++) {
        if (*p != '%') {
            put(&out, *p);
            continue;
        }
        p++;
        int left = 0, zero = 0, width = 0, is_long = 0;
        for (;; p++) {
            if (*p == '-') left = 1;
            else if (*p == '0') zero = 1;
            else break;
        }
        while (*p >= '0' && *p <= '9') width = width * 10 + (*p++ - '0');
        if (*p == 'l') {
            is_long = 1;
            p++;
        }
        switch (*p) {
        case 'd':
        case 'i': {
            long value = is_long ? va_arg(args, long) : va_arg(args, int);
            unsigned long magnitude = value < 0 ? 0 - (unsigned long)value : (unsigned long)value;
            put_number(&out, magnitude, value < 0, 10, 0, width, left, zero);
            break;
        }
        case 'u':
        case 'x':
        case 'X': {
            unsigned long value = is_long ? va_arg(args, unsigned long) : va_arg(args, unsigned);
            put_number(&out, value, 0, *p == 'u' ? 10 : 16, *p == 'X', width, left, zero);
            break;
        }
        case 'c': {
            char c = (char)va_arg(args, int);
            if (!left) put_repeated(&out, ' ', width - 1);
            put(&out, c);
            if (left) put_repeated(&out, ' ', width - 1);
            break;
        }
        case 's': {
            const char *s = va_arg(args, const char *);
            int length = 0;
            while (s[length]) length++;
            if (!left) put_repeated(&out, ' ', width - length);
            for (int i = 0; i < length; i++) put(&out, s[i]);
            if (left) put_repeated(&out, ' ', width - length);
            break;
        }
        case '%':
            put(&out, '%');
            break;
        default:
            put(&out, '%');
            if (*p) put(&out, *p);
            else p--;
            break;
        }
    }
    va_end(args);
    if (out.size) out.buffer[out.length < out.size ? out.length : out.size - 1] = 0;
    return (int)out.length;
}

int main(void) {
    char buffer[96];
    int length = format(buffer, sizeof buffer, "%s=%d|%5u|%-4x|%c%%|%08ld|%lX|%-6s|%3c|%i", "key", -42,
                        7u, 0xabu, 'Z', -123456L, 0xdeadbeefUL, "ok", 'q', 0);
