/** Writes count bytes from buf to the descriptor fd; returns the count written or a negative errno. */
static inline long sim_write(long fd, const void *buf, long count) {
    register long rax __asm__("rax") = 1;
    register long rdi __asm__("rdi") = fd;
    register const void *rsi __asm__("rsi") = buf;
    register long rdx __asm__("rdx") = count;
    __asm__ volatile("syscall" : "+r"(rax) : "r"(rdi), "r"(rsi), "r"(rdx) : "rcx", "r11", "memory");
    return rax;
}

/** Ends the calling thread with a status. */
__attribute__((noreturn)) static inline void sim_exit(long status) {
    register long rax __asm__("rax") = 60;
    register long rdi __asm__("rdi") = status;
    __asm__ volatile("syscall" : : "r"(rax), "r"(rdi) : "rcx", "r11", "memory");
    __builtin_unreachable();
}

